namespace PanoramicData.SoundPrint.Postgres;

/// <summary>A row of the <c>tracks</c> table: one fingerprinted track.</summary>
public sealed class TrackRecord
{
	/// <summary>The store's integer for the track, generated by the database. Landmarks reference it.</summary>
	public int Idx { get; set; }

	/// <summary>The caller's opaque track id. Unique.</summary>
	public required string TrackId { get; set; }

	/// <summary>How many landmarks the track was stored with.</summary>
	public int LandmarkCount { get; set; }

	/// <summary>When the track was added, in UTC.</summary>
	public DateTime CreatedUtc { get; set; }
}

/// <summary>A row of the <c>fingerprints</c> table: one landmark of one track. The table has no key; inserts use binary COPY.</summary>
public sealed class FingerprintRecord
{
	/// <summary>The 32-bit landmark hash, stored as a signed integer with the same bits.</summary>
	public int Hash { get; set; }

	/// <summary>The <see cref="TrackRecord.Idx"/> of the track this landmark belongs to.</summary>
	public int Track { get; set; }

	/// <summary>The frame of the landmark within the track.</summary>
	public int Frame { get; set; }
}

/// <summary>The single row of the <c>store_info</c> table, recording which fingerprint parameters the store was built with.</summary>
public sealed class StoreInfoRecord
{
	/// <summary>Always 1.</summary>
	public int Id { get; set; }

	/// <summary>The <see cref="FingerprintOptions.ParameterFingerprint"/> every landmark in the store was extracted with.</summary>
	public long ParameterFingerprint { get; set; }

	/// <summary>When the store was initialised, in UTC.</summary>
	public DateTime CreatedUtc { get; set; }
}
